 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    # The solid divider separates equal-width noisy masks.
    sep = next(c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1)
    width = min(sep, w - sep - 1)
    left = [grid[r][:width] for r in range(h)]
    right = [grid[r][sep + 1:sep + 1 + width] for r in range(h)]

    def foreground(region):
        counts = Counter(v for row in region for v in row)
        # Each half consists of a dominant background and sparse marks.
        return min(counts, key=counts.get)

    left_mark = foreground(left)
    right_mark = foreground(right)
    # The right-hand mark color is the canvas color; intersections are highlighted.
    out = [[right_mark for _ in range(width)] for _ in range(h)]
    for r in range(h):
        for c in range(width):
            if left[r][c] == left_mark and right[r][c] == right_mark:
                out[r][c] = 3
    return out

