def transform(grid):
    h, w = len(grid), len(grid[0])
    separators = []
    for r in range(h):
        if len(set(grid[r])) == 1 and r > 0 and r < h - 1:
            if r == h - r - 1:
                separators.append(("horizontal", r, grid[r][0]))
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)) and c > 0 and c < w - 1:
            if c == w - c - 1:
                separators.append(("vertical", c, grid[0][c]))

    if not separators:
        # Fallback for unequal halves: choose the constant line with closest
        # side lengths, favoring the line that most clearly separates colors.
        candidates = []
        for r in range(1, h - 1):
            if len(set(grid[r])) == 1:
                candidates.append((abs(r - (h - r - 1)), "horizontal", r, grid[r][0]))
        for c in range(1, w - 1):
            if all(grid[r][c] == grid[0][c] for r in range(h)):
                candidates.append((abs(c - (w - c - 1)), "vertical", c, grid[0][c]))
        _, orientation, pos, _ = min(candidates)
    else:
        orientation, pos, _ = separators[0]

    if orientation == "vertical":
        left = [row[:pos] for row in grid]
        right = [row[pos + 1:2 * pos + 1] for row in grid]
    else:
        left = grid[:pos]
        right = grid[pos + 1:2 * pos + 1]

    common = set(v for row in left for v in row) & set(v for row in right for v in row)
    # The shared color is the signal color that forms the output canvas.
    shared = min(common, key=lambda v: (sum(x == v for row in left for x in row) +
                                        sum(x == v for row in right for x in row), v))
    out = [[shared for _ in row] for row in left]
    for r in range(len(left)):
        for c in range(len(left[r])):
            if left[r][c] == shared and right[r][c] == shared:
                out[r][c] = 3
    return out

if __name__ == '__main__':
